"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type FocusEvent, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One person who can be assigned. */
export interface AssigneePerson {
  id: string;
  name: string;
  /** One or two letters for the avatar. Defaults to the first letters of the first and last name. */
  initials?: string;
  /** A second line in the list, such as a role. */
  detail?: string;
  /** A background class for the avatar, such as `bg-chart-2/20`. Defaults to a chart token by position. */
  tone?: string;
}

/** Props for a pill button that shows who is assigned and opens a list to change it. */
export type AssigneePickerProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue" | "onChange"> & {
  people: AssigneePerson[];
  /** The ids of the people assigned. */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (ids: string[]) => void;
  /** Names the button and the list, for example "Assignees". */
  label?: string;
  /** The button text while nobody is assigned. */
  emptyLabel?: string;
  /** How many avatars the button shows before it counts the rest as "+N". */
  max?: number;
};

// Damping 46 is above 2 × √520, so an avatar settles into the stack without overshoot.
const ENTER: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
// Reduced motion drops the scale and the slide and keeps a short fade.
const FADE: Transition = { duration: 0.15 };
// The list is summoned often, so it shows at once and only fades out.
const LIST_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const TONES = ["bg-chart-1/20", "bg-chart-2/20", "bg-chart-4/20", "bg-chart-5/20", "bg-chart-3/20"];

// Words that end a name without being part of the initials, such as "Jr." or "III".
const NAME_SUFFIXES = new Set(["JR", "SR", "II", "III", "IV", "V"]);
// Firefox before 125 has no Intl.Segmenter. There the first code point stands in, which keeps an accented letter whole.
const graphemes =
  Intl.Segmenter ? new Intl.Segmenter(undefined, { granularity: "grapheme" }) : null;
const firstGrapheme = (word: string) =>
  graphemes ? (graphemes.segment(word)[Symbol.iterator]().next().value?.segment ?? "") : (Array.from(word)[0] ?? "");
const isSuffix = (word: string) => NAME_SUFFIXES.has(word.replaceAll(".", "").toUpperCase());

// The first character a reader sees in the first and the last word, so an emoji or an accented
// letter stays whole. A suffix counts only at the end, so "V. Patel" keeps its V. An empty result
// means the caller shows a person glyph instead.
function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  while (words.length > 1 && isSuffix(words[words.length - 1])) words.pop();
  if (words.length === 0) return "";
  const picked = words.length > 1 ? [words[0], words[words.length - 1]] : [words[0]];
  return picked.map(firstGrapheme).join("").toUpperCase();
}

function PersonGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <circle cx="8" cy="5" r="2.75" />
      <path d="M3 13.25C3 10.75 5.2 9 8 9s5 1.75 5 4.25c0 .4-.35.75-.75.75h-8.5A.75.75 0 0 1 3 13.25Z" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m3 8.5 3.25 3.25L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function ChevronGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-3.5 text-muted-foreground">
      <path d="M3.6 5.8a.9.9 0 0 1 1.27 0L8 8.93l3.13-3.13a.9.9 0 1 1 1.27 1.27l-3.76 3.77a.9.9 0 0 1-1.28 0L3.6 7.07a.9.9 0 0 1 0-1.27Z" />
    </svg>
  );
}

function AddPersonGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <circle cx="6.5" cy="5" r="2.75" />
      <path d="M1.5 13.25c0-2.5 2.2-4.25 5-4.25s5 1.75 5 4.25c0 .4-.35.75-.75.75h-8.5a.75.75 0 0 1-.75-.75ZM12.75 3.5c.41 0 .75.34.75.75v1h1a.75.75 0 0 1 0 1.5h-1v1a.75.75 0 0 1-1.5 0v-1h-1a.75.75 0 0 1 0-1.5h1v-1c0-.41.34-.75.75-.75Z" />
    </svg>
  );
}

// The card-coloured base keeps a tinted avatar opaque, so the one under it in the stack never shows through.
function Avatar({ person, tone }: { person: AssigneePerson; tone: string }) {
  return (
    <span className="flex size-7 shrink-0 rounded-full bg-card ring-2 ring-card">
      <span className={cn("grid size-full place-items-center rounded-full text-xs font-medium text-foreground", tone)}>
        {person.initials ?? (initialsOf(person.name) || <PersonGlyph />)}
      </span>
    </span>
  );
}

/**
 * A pill button that shows the people assigned as a stack of avatars and opens
 * a list to change them. Picking a person adds their avatar to the stack with a
 * small enter animation, and unpicking removes it.
 */
export function AssigneePicker({
  people,
  value: valueProp,
  defaultValue = [],
  onValueChange,
  label = "Assignees",
  emptyLabel = "Assign",
  max = 3,
  className,
  onBlur,
  ...divProps
}: AssigneePickerProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const selected = valueProp ?? ownValue;
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  // The list can shrink while it is open, so the active row is read through a clamp and never names a missing option.
  const activeIndex = Math.max(Math.min(active, people.length - 1), 0);
  const reduceMotion = useReducedMotion();
  const listId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  // Marks which edges of the open list have items under them, so only those edges fade.
  // It writes data attributes on the list itself: a scroll position needs no re-render.
  const markEdges = (list: HTMLUListElement) => {
    list.dataset.top = String(list.scrollTop > 1);
    list.dataset.bottom = String(list.scrollTop + list.clientHeight < list.scrollHeight - 1);
  };
  const setList = (list: HTMLUListElement | null) => {
    listRef.current = list;
    if (list) markEdges(list);
  };

  const toneOf = (person: AssigneePerson) => person.tone ?? TONES[people.indexOf(person) % TONES.length];
  const optionId = (index: number) => `${listId}-option-${index}`;
  const assigned = people.filter((person) => selected.includes(person.id));
  const shown = assigned.slice(0, max);
  const extra = assigned.length - shown.length;

  // Focus sits on the list, and the list points at the active person.
  useEffect(() => {
    if (open) listRef.current?.focus();
  }, [open]);

  useEffect(() => {
    if (!open) return;
    listRef.current?.querySelector('[data-active="true"]')?.scrollIntoView?.({ block: "nearest" });
  }, [open, activeIndex]);

  // A press outside closes the list. Focus stays where the person pressed.
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: PointerEvent) => {
      if (event.target instanceof Node && !rootRef.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const toggle = (id: string) => {
    const next = selected.includes(id) ? selected.filter((item) => item !== id) : [...selected, id];
    if (valueProp === undefined) setOwnValue(next);
    onValueChange?.(next);
  };

  const openList = () => {
    const firstAssigned = people.findIndex((person) => selected.includes(person.id));
    setActive(Math.max(firstAssigned, 0));
    setOpen(true);
  };

  const closeToButton = () => {
    setOpen(false);
    buttonRef.current?.focus();
  };

  const handleButtonKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (open || (event.key !== "ArrowDown" && event.key !== "ArrowUp")) return;
    event.preventDefault();
    openList();
  };

  const handleListKeyDown = (event: KeyboardEvent<HTMLUListElement>) => {
    const last = people.length - 1;
    const moves = new Map([
      ["ArrowDown", Math.min(activeIndex + 1, last)],
      ["ArrowUp", Math.max(activeIndex - 1, 0)],
      ["Home", 0],
      ["End", last],
    ]);
    const move = moves.get(event.key);
    if (move !== undefined) setActive(move);
    else if (event.key === " " || event.key === "Enter") {
      if (people[activeIndex]) toggle(people[activeIndex].id);
    } else if (event.key === "Escape") closeToButton();
    else return;
    event.preventDefault();
  };

  // Focus leaving the whole picker closes the list, whether it leaves from the list or from the button.
  const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
    onBlur?.(event);
    if (open && !rootRef.current?.contains(event.relatedTarget)) setOpen(false);
  };

  // An avatar grows in from half size and fades. The ones beside it slide to their new place with a layout
  // animation, which moves them with transforms; `popLayout` takes a leaving avatar out of the row at once.
  const hiddenSlot = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.5 };
  const shownSlot = { opacity: 1, scale: 1 };
  const slotTransition = reduceMotion ? FADE : ENTER;
  const slotLayout = reduceMotion ? false : "position";
  const names = assigned.map((person) => person.name).join(", ");

  return (
    <div {...divProps} ref={rootRef} onBlur={handleBlur} className={cn("relative inline-flex", className)}>
      <button
        ref={buttonRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
        aria-label={`${label}: ${names || "none"}`}
        // Keeps focus in the list while the button is pressed, so the press
        // closes the list once instead of a blur closing it and the click reopening it.
        onMouseDown={(event) => {
          if (open) event.preventDefault();
        }}
        onClick={() => (open ? closeToButton() : openList())}
        onKeyDown={handleButtonKeyDown}
        className="inline-flex min-h-11 cursor-pointer touch-manipulation items-center gap-2 rounded-full border border-border bg-card px-2 py-1 text-sm font-medium text-foreground outline-none hover:bg-muted active:scale-97 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition motion-safe:duration-150 sm:min-h-9"
      >
        {/* Each avatar after the first overlaps the one before it by a quarter of its width. */}
        <span className="flex items-center *:not-first:-ml-2">
          <AnimatePresence initial={false} mode="popLayout">
            {shown.map((person) => (
              <motion.span
                key={`person:${person.id}`}
                layout={slotLayout}
                initial={hiddenSlot}
                animate={shownSlot}
                exit={hiddenSlot}
                transition={slotTransition}
                className="flex shrink-0"
              >
                <Avatar person={person} tone={toneOf(person)} />
              </motion.span>
            ))}
            {extra > 0 ? (
              <motion.span
                key="extra"
                layout={slotLayout}
                initial={hiddenSlot}
                animate={shownSlot}
                exit={hiddenSlot}
                transition={slotTransition}
                className="flex shrink-0"
              >
                <span className="grid size-7 shrink-0 place-items-center rounded-full bg-muted text-xs font-medium text-foreground tabular-nums ring-2 ring-card">
                  +{extra}
                </span>
              </motion.span>
            ) : null}
          </AnimatePresence>
        </span>
        {assigned.length === 0 ? (
          <>
            <span className="grid size-7 place-items-center rounded-full bg-muted text-muted-foreground">
              <AddPersonGlyph />
            </span>
            {emptyLabel}
          </>
        ) : null}
        <motion.span layout={slotLayout} transition={slotTransition} className="flex">
          <ChevronGlyph />
        </motion.span>
      </button>
      <AnimatePresence>
        {open ? (
          <motion.ul
            key="list"
            ref={setList}
            id={listId}
            role="listbox"
            aria-multiselectable="true"
            aria-label={label}
            aria-activedescendant={people.length > 0 ? optionId(activeIndex) : undefined}
            tabIndex={-1}
            onKeyDown={handleListKeyDown}
            onScroll={(event) => markEdges(event.currentTarget)}
            initial={false}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0, pointerEvents: "none", transition: reduceMotion ? { duration: 0 } : LIST_OUT }}
            className={cn(
              "group absolute top-full left-0 z-50 mt-2 max-h-72 w-64 origin-top-left overflow-y-auto rounded-xl border border-border bg-popover p-1 text-popover-foreground shadow-lg outline-none [scrollbar-width:none]",
              "data-[top=true]:mask-t-from-85% data-[bottom=true]:mask-b-from-85%",
            )}
          >
            {people.map((person, index) => {
              const isSelected = selected.includes(person.id);
              return (
                <li
                  key={person.id}
                  id={optionId(index)}
                  role="option"
                  aria-selected={isSelected}
                  data-active={index === activeIndex}
                  onClick={() => {
                    setActive(index);
                    toggle(person.id);
                  }}
                  className="flex min-h-11 cursor-pointer touch-manipulation items-center gap-3 rounded-lg px-2 py-1 text-sm ring-ring ring-inset hover:bg-muted data-[active=true]:bg-muted group-focus-visible:data-[active=true]:ring-2 sm:min-h-9"
                >
                  <Avatar person={person} tone={toneOf(person)} />
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="truncate">{person.name}</span>
                    {person.detail ? <span className="truncate text-xs text-muted-foreground">{person.detail}</span> : null}
                  </span>
                  <span
                    className={cn(
                      "flex shrink-0 motion-safe:transition motion-safe:duration-150",
                      isSelected ? "scale-100 opacity-100" : "scale-50 opacity-0",
                    )}
                  >
                    <CheckGlyph />
                  </span>
                </li>
              );
            })}
          </motion.ul>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
